import { useMount } from 'ahooks';
import { useState } from 'react';
const DEFAULT_STATUS = {
    data: null,
    isPending: true,
    isValidate: false,
};
const SUCCESS_STATUS = {
    isPending: false,
    isValidate: false,
};
const FAIL_STATUS = {
    isPending: false,
    isValidate: true,
};
/**
 * use
 * @description use promise
 * @param { data: any; isPending: boolean; isValidate: boolean; } p
 * @param defaultArgs
 */
const use = (p, defaultArgs) => {
    const [result, setResult] = useState({
        ...DEFAULT_STATUS,
    });
    const [type, setType] = useState('reset');
    /**
     * executePromise
     * @description execute promise
     * @param {any[]} _defaultArgs
     */
    function executePromise(_defaultArgs) {
        // @ts-ignore
        p?.apply?.(this, _defaultArgs)
            ?.then((res) => {
            setResult({
                data: res,
                ...SUCCESS_STATUS,
            });
        })
            .catch((err) => {
            setResult({
                data: err,
                ...FAIL_STATUS,
            });
        });
    }
    /**
     * reset
     * @description 重新调用接口
     * @param {any[]} args
     */
    function reset(...args) {
        setResult({
            ...DEFAULT_STATUS,
        });
        setType('reset');
        executePromise(args);
    }
    /**
     * reload
     * @description 重新调用接口
     * @param {any[]} args
     */
    function reload(...args) {
        setResult({
            ...DEFAULT_STATUS,
            data: result.data,
        });
        setType('reload');
        executePromise(args);
    }
    useMount(() => {
        executePromise(defaultArgs ?? []);
    });
    return {
        ...result,
        type,
        reset,
        reload,
    };
};
export default use;
